/* Same result as RtlUpcaseUnicodeChar with the l_intl.nls table loaded */
static __inline unsigned short
NlsUpcaseTableChar(unsigned short Source)
{
    unsigned short Offset;

    if (Source < 'a')
        return Source;
    if (Source <= 'z')
        return (unsigned short)(Source - ('a' - 'A'));

    Offset = NlsUpcaseTable[Source >> 8];
    Offset = NlsUpcaseTable[Offset + ((Source >> 4) & 0xF)];
    Offset = NlsUpcaseTable[Offset + (Source & 0xF)];
    return (unsigned short)(Source + (short)Offset);
}

